2	  findPlayer,
3	  type LedgerCache,
4	  type LedgerPlayer,
5	  type LedgerRubbing,
6	  type LedgerState,
7	  type Position,
8	  type RubbingLocation,
9	} from "./state.js";
10	
11	/**
12	 * Why a request changed nothing (§16: duplicate, stale, unauthorised or already-resolved requests return the current
13	 * result without mutating state). A rejected request always returns the very state object it was given.
14	 */
15	export type LedgerRejection =
16	  | "invalid-request"
17	  | "stale-tick"
18	  | "duplicate"
19	  | "unknown-player"
20	  | "player-left"
21	  | "player-disconnected"
22	  | "player-in-duel"
23	  | "same-player"
24	  | "unknown-source"
25	  | "source-locked"
26	  | "source-empty"
27	  | "type-held"
28	  | "unknown-cache"
29	  | "not-in-cache"
30	  | "no-channel"
31	  | "unknown-duel"
32	  | "not-a-participant"
33	  | "already-resolved"
34	  | "not-choosing"
35	  | "not-winner"
36	  | "choice-window-closed"
37	  | "ineligible-type"
38	  | "not-disconnected"
39	  | "reservation-active"
40	  | "reservation-expired"
41	  | "already-claimed"
42	  | "insufficient-gold"
43	  | "tonic-limit"
44	  | "no-tonic"
45	  | "tonic-active"
46	  | "not-at-sea"
47	  | "grappled";
48	
49	/** One rubbing move, for §16's transfer record. `revisionAfter` is always `revisionBefore + 1`. */
50	export interface Transfer {
51	  readonly rubbingId: string;
52	  readonly from: RubbingLocation;
53	  readonly to: RubbingLocation;
54	  readonly revisionBefore: number;
55	  readonly revisionAfter: number;
56	}
57	
58	/** What every operation returns: the next state (the same object when nothing changed) and its result. */
59	export interface LedgerStep<R> {
60	  readonly state: LedgerState;
61	  readonly result: R;
62	}
63	
64	/** Moves made so far by one operation, and the caches it opened. */
65	export interface Effects {
66	  readonly transfers: Transfer[];
67	  readonly cacheIds: string[];
68	}
69	
70	export function noEffects(): Effects {
71	  return { transfers: [], cacheIds: [] };
72	}
73	
74	function isSafeInteger(value: unknown): value is number {
75	  return typeof value === "number" && Number.isSafeInteger(value);
76	}
77	
78	export function isPlayerId(value: unknown): value is string {
79	  return typeof value === "string" && value.length > 0;
80	}
81	
82	export function isPosition(value: unknown): value is Position {
83	  if (typeof value !== "object" || value === null) return false;
84	  const { x, y } = value as Record<string, unknown>;
85	  return isSafeInteger(x) && isSafeInteger(y);
86	}
87	
88	/** A request's tick must be a non-negative integer no earlier than the ledger's latest. */
89	export function tickRejection(state: LedgerState, tick: unknown): LedgerRejection | null {
90	  if (!isSafeInteger(tick) || tick < 0) return "invalid-request";
91	  return tick < state.tick ? "stale-tick" : null;
92	}
93	
94	export function atTick(state: LedgerState, tick: number): LedgerState {
95	  return tick === state.tick ? state : { ...state, tick };
96	}
97	
98	/** Why a player cannot act in the world right now, if they cannot. */
99	export function playerRejection(state: LedgerState, playerId: unknown): LedgerRejection | null {
100	  if (!isPlayerId(playerId)) return "invalid-request";
101	  const player = findPlayer(state, playerId);
102	  if (!player) return "unknown-player";
103	  return player.status === "left" ? "player-left" : null;
104	}
105	
106	export function updatePlayer(
107	  state: LedgerState,
108	  playerId: string,
109	  update: (player: LedgerPlayer) => LedgerPlayer,
110	): LedgerState {
111	  return { ...state, players: state.players.map((player) => (player.id === playerId ? update(player) : player)) };
112	}
